/**
 * Spending Report aggregation (pure)
 *
 * Rolls a year's Expenses up through the hierarchy
 *   Category → Grouping → Area of Importance
 * into the month-by-month grid the report renders. No I/O, no dates-from-clock,
 * no Supabase — a plain function so it can be unit-tested like the CSV parsers.
 *
 * Design: docs/plans/2026-07-09-spending-report-design.md
 *
 * Conventions baked in here (all settled during the grill):
 * - Source is Expenses (receipts), bucketed by `transaction_date` (purchase date).
 * - Amounts are normalized to the family's currency via the stored FX rate:
 *   amount * (exchange_rate_to_cad ?? 1). Refunds are negative and are KEPT
 *   negative so they net out (unlike the CSV/PDF exporters, which abs them).
 * - Visible month columns run January → the last month that has any expense.
 * - A cell with no receipts renders blank; a cell with receipts summing to 0
 *   renders 0.00. So each cell carries both an amount and a receipt count.
 * - Rows are only emitted where there was activity (zero-activity suppression is
 *   automatic — we build rows from the data, not from the full hierarchy).
 * - Categories with no Grouping (group_id null / unknown) and receipts with no
 *   category land in a bottom "Uncategorized" section, which IS included in the
 *   grand total.
 */

import type { ImportanceArea, CategoryGroup } from '$lib/types/Hierarchy';

// Re-export the hierarchy types so callers can import them from here too.
export type { ImportanceArea, CategoryGroup } from '$lib/types/Hierarchy';

/** The fields of an Expense this aggregation needs. `Expense` satisfies it structurally. */
export interface SpendingExpense {
	total_amount: number | null;
	transaction_date: string; // 'YYYY-MM-DD'
	category_id: string | null;
	exchange_rate_to_cad: number | null;
}

/** Minimal category shape needed to resolve a receipt to its Grouping. */
export interface SpendingCategory {
	id: string;
	name: string;
	group_id?: string | null;
}

/** One month/YTD cell: the summed amount plus how many receipts contributed. */
export interface Cell {
	amount: number;
	count: number;
}

/** A single printed line: a category, a subtotal, or the grand total. */
export interface ReportRow {
	name: string;
	/**
	 * The category this row maps to 1:1, for drill-down into the Expenses view.
	 * Set on category detail rows (including a named-but-ungrouped Uncategorized
	 * row); undefined on the "(No category)" row and on all subtotal/grand-total
	 * rows. See `spendingDrilldown.ts`.
	 */
	categoryId?: string;
	/** One cell per visible month (parallel to `SpendingReport.months`). */
	cells: Cell[];
	/** Year-to-date roll-up across the visible months. */
	ytd: Cell;
}

/** A Grouping and its category rows, with the group subtotal. */
export interface GroupSection {
	name: string;
	/** The Grouping's id, for drill-down; undefined for the synthetic Uncategorized section. */
	id?: string;
	rows: ReportRow[];
	subtotal: ReportRow;
}

/** An Area of Importance and its groups, with the importance subtotal. */
export interface ImportanceSection {
	name: string;
	/** The Area of Importance's id, for drill-down. */
	id: string;
	sortOrder: number;
	groups: GroupSection[];
	subtotal: ReportRow;
}

export interface SpendingReport {
	year: number;
	/** 1-based month numbers shown as columns, e.g. [1,2,3,4,5,6]. Empty if no data. */
	months: number[];
	/** Short labels parallel to `months`, e.g. ['Jan','Feb',...]. */
	monthLabels: string[];
	importances: ImportanceSection[];
	/** Uncategorized spend as its own section; null when everything is categorized. */
	uncategorized: GroupSection | null;
	/** Bottom-right roll-up across everything, including Uncategorized. */
	grandTotal: ReportRow;
	/** Receipts in `year` with a null amount (counted as $0). Surfaced as a footnote. */
	missingAmountCount: number;
}

const MONTH_LABELS = [
	'Jan',
	'Feb',
	'Mar',
	'Apr',
	'May',
	'Jun',
	'Jul',
	'Aug',
	'Sep',
	'Oct',
	'Nov',
	'Dec'
];

const UNCATEGORIZED_SECTION = 'Uncategorized';
const NO_CATEGORY_ROW = '(No category)';

/**
 * Parse the year and 1-based month out of a 'YYYY-MM-DD' string without
 * constructing a Date — bare date strings parse as UTC midnight and can shift a
 * day (and thus a month) west of UTC. Returns null for anything unparseable.
 */
function yearMonth(dateStr: string): { year: number; month: number } | null {
	if (!dateStr || dateStr.length < 7) return null;
	const year = Number(dateStr.slice(0, 4));
	const month = Number(dateStr.slice(5, 7));
	if (!Number.isInteger(year) || !Number.isInteger(month) || month < 1 || month > 12) {
		return null;
	}
	return { year, month };
}

/** CAD (family-currency) value of an expense; refunds stay negative. */
function normalizedAmount(e: SpendingExpense): number {
	if (e.total_amount == null) return 0;
	return e.total_amount * (e.exchange_rate_to_cad ?? 1);
}

function emptyCells(monthCount: number): Cell[] {
	return Array.from({ length: monthCount }, () => ({ amount: 0, count: 0 }));
}

function addInto(target: Cell, amount: number): void {
	target.amount += amount;
	target.count += 1;
}

/** Accumulate one row's cells (and ytd) into another (for subtotals/grand total). */
function accumulate(target: ReportRow, source: ReportRow): void {
	for (let i = 0; i < source.cells.length; i++) {
		target.cells[i].amount += source.cells[i].amount;
		target.cells[i].count += source.cells[i].count;
	}
	target.ytd.amount += source.ytd.amount;
	target.ytd.count += source.ytd.count;
}

function makeRow(name: string, monthCount: number, categoryId?: string): ReportRow {
	return { name, categoryId, cells: emptyCells(monthCount), ytd: { amount: 0, count: 0 } };
}

/**
 * Internal accumulator keyed by group then category, so we can build the tree in
 * one pass over the expenses and sort/emit it at the end.
 */
interface GroupAccumulator {
	name: string;
	/** The Grouping's id; undefined for the synthetic Uncategorized bucket. */
	id?: string;
	rows: Map<string, ReportRow>; // category name → row
}

/**
 * Build the spending report grid for a single calendar year.
 *
 * @param expenses      All expenses (the caller may pass more than `year`; we filter).
 * @param categories    Family categories, each carrying its `group_id`.
 * @param groups        Family groupings, each carrying its `importance_area_id`.
 * @param importanceAreas Family importance areas with `sort_order`.
 * @param year          The calendar year to report on.
 */
export function buildSpendingReport(
	expenses: SpendingExpense[],
	categories: SpendingCategory[],
	groups: CategoryGroup[],
	importanceAreas: ImportanceArea[],
	year: number
): SpendingReport {
	// --- lookups -------------------------------------------------------------
	const categoryById = new Map(categories.map((c) => [c.id, c]));
	const groupById = new Map(groups.map((g) => [g.id, g]));
	const importanceById = new Map(importanceAreas.map((a) => [a.id, a]));

	// --- pass 1: which months are in play, and the missing-amount count --------
	let maxMonth = 0;
	let missingAmountCount = 0;
	const inYear: { e: SpendingExpense; month: number }[] = [];
	for (const e of expenses) {
		const ym = yearMonth(e.transaction_date);
		if (!ym || ym.year !== year) continue;
		inYear.push({ e, month: ym.month });
		if (ym.month > maxMonth) maxMonth = ym.month;
		if (e.total_amount == null) missingAmountCount += 1;
	}

	if (maxMonth === 0) {
		// No expenses this year — empty report (component shows an empty state).
		return {
			year,
			months: [],
			monthLabels: [],
			importances: [],
			uncategorized: null,
			grandTotal: makeRow('Grand Total', 0),
			missingAmountCount: 0
		};
	}

	const months = Array.from({ length: maxMonth }, (_, i) => i + 1);
	const monthLabels = months.map((m) => MONTH_LABELS[m - 1]);
	const monthCount = months.length;
	const monthIndex = (m: number) => m - 1; // month 1 → column 0

	// --- pass 2: bucket each expense into importance → group → category --------
	// Keyed by importance area id; a synthetic key holds the Uncategorized bucket.
	const importanceAcc = new Map<string, Map<string, GroupAccumulator>>();
	const uncategorizedAcc: GroupAccumulator = { name: UNCATEGORIZED_SECTION, rows: new Map() };

	const ensureRow = (acc: GroupAccumulator, name: string, categoryId?: string): ReportRow => {
		let row = acc.rows.get(name);
		if (!row) {
			row = makeRow(name, monthCount, categoryId);
			acc.rows.set(name, row);
		}
		return row;
	};

	for (const { e, month } of inYear) {
		const amount = normalizedAmount(e);
		const category = e.category_id != null ? categoryById.get(e.category_id) : undefined;
		const group = category?.group_id != null ? groupById.get(category.group_id) : undefined;
		const importance = group ? importanceById.get(group.importance_area_id) : undefined;

		let targetGroupAcc: GroupAccumulator;
		let rowName: string;

		if (category && group && importance) {
			let groupsForImportance = importanceAcc.get(importance.id);
			if (!groupsForImportance) {
				groupsForImportance = new Map();
				importanceAcc.set(importance.id, groupsForImportance);
			}
			let groupAcc = groupsForImportance.get(group.id);
			if (!groupAcc) {
				groupAcc = { name: group.name, id: group.id, rows: new Map() };
				groupsForImportance.set(group.id, groupAcc);
			}
			targetGroupAcc = groupAcc;
			rowName = category.name;
		} else {
			// Uncategorized: no category, unknown category, category without a group,
			// or a group/importance that no longer resolves.
			targetGroupAcc = uncategorizedAcc;
			rowName = category ? category.name : NO_CATEGORY_ROW;
		}

		// A named row (even in Uncategorized) carries its real category id; the
		// "(No category)" catch-all stays id-less.
		const row = ensureRow(targetGroupAcc, rowName, category?.id);
		addInto(row.cells[monthIndex(month)], amount);
		addInto(row.ytd, amount);
	}

	// --- emit: sort and roll up subtotals -------------------------------------
	const buildGroupSection = (acc: GroupAccumulator, subtotalName: string): GroupSection => {
		const rows = [...acc.rows.values()].sort((a, b) => byName(a.name, b.name));
		const subtotal = makeRow(subtotalName, monthCount);
		for (const row of rows) accumulate(subtotal, row);
		return { name: acc.name, id: acc.id, rows, subtotal };
	};

	const sortedImportances = [...importanceAreas]
		.filter((a) => importanceAcc.has(a.id))
		.sort((a, b) => a.sort_order - b.sort_order || byName(a.name, b.name));

	const importances: ImportanceSection[] = sortedImportances.map((area) => {
		const groupAccs = importanceAcc.get(area.id)!;
		const groupSections = [...groupAccs.values()]
			.map((g) => buildGroupSection(g, `${g.name} Total`))
			.sort((a, b) => byName(a.name, b.name));
		const subtotal = makeRow(`${area.name} Total`, monthCount);
		for (const gs of groupSections) accumulate(subtotal, gs.subtotal);
		return {
			name: area.name,
			id: area.id,
			sortOrder: area.sort_order,
			groups: groupSections,
			subtotal
		};
	});

	const uncategorized =
		uncategorizedAcc.rows.size > 0
			? buildGroupSection(uncategorizedAcc, `${UNCATEGORIZED_SECTION} Total`)
			: null;

	// --- grand total (includes Uncategorized) ---------------------------------
	const grandTotal = makeRow('Grand Total', monthCount);
	for (const imp of importances) accumulate(grandTotal, imp.subtotal);
	if (uncategorized) accumulate(grandTotal, uncategorized.subtotal);

	return {
		year,
		months,
		monthLabels,
		importances,
		uncategorized,
		grandTotal,
		missingAmountCount
	};
}

/** Case-insensitive name sort, "(No category)" sinks to the bottom. */
function byName(a: string, b: string): number {
	if (a === NO_CATEGORY_ROW) return 1;
	if (b === NO_CATEGORY_ROW) return -1;
	return a.localeCompare(b, undefined, { sensitivity: 'base' });
}

