/**
 * Pure parser for the historical-expense CSV import.
 *
 * The family's spreadsheet export has the columns:
 *   Timestamp, Merchant, Amount, Category, Tag
 *
 * - **Timestamp** — the purchase date (`transaction_date`), any format
 *   `parseFlexibleDate` accepts (the export uses `YYYY-MM-DD`).
 * - **Amount** — positive for a purchase, negative for a refund. This is the
 *   **same sign convention as `receipts.total_amount`**, so the sign is kept
 *   verbatim (no inversion, no `abs()`); refunds net against spend in the
 *   Spending report exactly as they do for real receipts.
 * - **Category** — a plain name resolved to a category id later in the pipeline
 *   (blank → `null`, i.e. Uncategorized).
 * - **Tag** — there is no tag concept in the schema, so this column is ignored.
 *
 * Mirrors the bank-CSV parsers' style (pure, tolerant, collects per-row errors
 * instead of throwing) and reuses the same low-level primitives so tokenizing,
 * date, and amount handling stay identical. Design:
 * docs/plans/2026-07-09-spending-report-design.md
 */

import { tokenizeCsv, parseFlexibleDate, parseCsvAmount, removeBom } from './csvPrimitives';

/** One CSV row normalized into the fields a historical receipt needs. */
export interface ParsedExpenseImportRow {
	/** Purchase date, `YYYY-MM-DD`. */
	transaction_date: string;
	merchant_name: string;
	/** Sign kept as written: positive = expense, negative = refund. */
	total_amount: number;
	/** Category name, or `null` for a blank cell (Uncategorized). */
	categoryName: string | null;
}

export interface ExpenseImportParseResult {
	rows: ParsedExpenseImportRow[];
	/** Human-readable per-row / format problems; parsing never throws. */
	errors: string[];
}

/**
 * Accepted header names for each logical column (case-insensitive). The primary
 * name is the family export's; the aliases make the importer forgiving of a
 * hand-renamed header without inviting a whole configurable-mapping feature.
 */
const COLUMN_ALIASES = {
	transaction_date: ['timestamp', 'date'],
	merchant_name: ['merchant', 'vendor'],
	amount: ['amount'],
	category: ['category']
} as const;

type ColumnKey = keyof typeof COLUMN_ALIASES;

/** Resolve the 0-based index of each required column, or list the missing ones. */
function resolveColumns(header: string[]): {
	indices: Record<ColumnKey, number>;
	missing: ColumnKey[];
} {
	const normalized = header.map((h) => h.toLowerCase().trim());
	const indices = {} as Record<ColumnKey, number>;
	const missing: ColumnKey[] = [];

	for (const key of Object.keys(COLUMN_ALIASES) as ColumnKey[]) {
		const index = normalized.findIndex((h) => COLUMN_ALIASES[key].includes(h as never));
		indices[key] = index;
		if (index === -1) missing.push(key);
	}

	return { indices, missing };
}

export function parseExpenseImportCsv(csvText: string): ExpenseImportParseResult {
	const rows: ParsedExpenseImportRow[] = [];
	const errors: string[] = [];

	const grid = tokenizeCsv(removeBom(csvText));
	if (grid.length === 0) {
		errors.push('The file is empty.');
		return { rows, errors };
	}

	const { indices, missing } = resolveColumns(grid[0]);
	if (missing.length > 0) {
		errors.push(`CSV is missing required column(s): ${missing.join(', ')}.`);
		return { rows, errors };
	}

	for (let i = 1; i < grid.length; i++) {
		const row = grid[i];
		const rowNumber = i + 1; // 1-based, counting the header

		const rawDate = row[indices.transaction_date] ?? '';
		const transaction_date = parseFlexibleDate(rawDate);
		if (!transaction_date) {
			errors.push(`Row ${rowNumber}: unrecognized date "${rawDate.trim()}".`);
			continue;
		}

		const merchant_name = (row[indices.merchant_name] ?? '').trim();
		if (!merchant_name) {
			errors.push(`Row ${rowNumber}: missing merchant name.`);
			continue;
		}

		const rawAmount = row[indices.amount] ?? '';
		const total_amount = parseCsvAmount(rawAmount);
		if (total_amount === null) {
			errors.push(`Row ${rowNumber}: unrecognized amount "${rawAmount.trim()}".`);
			continue;
		}

		const rawCategory = (row[indices.category] ?? '').trim();
		const categoryName = rawCategory === '' ? null : rawCategory;

		rows.push({ transaction_date, merchant_name, total_amount, categoryName });
	}

	return { rows, errors };
}

