1	/**
2	 * Low-level CSV primitives shared by the bank-transaction parsers
3	 * (`BaseCSVParser`) and the historical-expense importer (`expenseImportCsv`).
4	 *
5	 * These were originally protected methods on `BaseCSVParser`; they are extracted
6	 * here as pure functions so a second consumer can reuse the exact same
7	 * tokenizer / date / amount handling without subclassing a bank parser or
8	 * duplicating the logic. `BaseCSVParser` now delegates to them, so the 7 bank
9	 * parsers' test suites act as the oracle guaranteeing behaviour is unchanged.
10	 */
11	
12	const MONTH_ABBREVIATIONS: Record<string, string> = {
13		jan: '01',
14		feb: '02',
15		mar: '03',
16		apr: '04',
17		may: '05',
18		jun: '06',
19		jul: '07',
20		aug: '08',
21		sep: '09',
22		oct: '10',
23		nov: '11',
24		dec: '12'
25	};
26	
27	const MONTH_FULL_NAMES: Record<string, string> = {
28		january: '01',
29		february: '02',
30		march: '03',
31		april: '04',
32		may: '05',
33		june: '06',
34		july: '07',
35		august: '08',
36		september: '09',
37		october: '10',
38		november: '11',
39		december: '12'
40	};
41	
42	/**
43	 * Tokenize a CSV string into rows and columns.
44	 *
45	 * Handles quoted fields containing commas, escaped `""` quotes, and strips a
46	 * surviving surrounding `"..."` pair left by double-encoded exports (EQ Bank
47	 * emits `"""-$33.00"""`). Blank lines are skipped.
48	 */
49	export function tokenizeCsv(csvContent: string): string[][] {
50		const lines = csvContent.split(/\r?\n/);
51		const result: string[][] = [];
52	
53		// Strip a surviving surrounding "..." pair from a finalized field.
54		// EQ Bank exports double-encoded values like `"""-$33.00"""`, which the
55		// standard unwrap above reduces to `"-$33.00"` (literal " still present).
56		const stripOuterQuotes = (field: string): string => {
57			const trimmed = field.trim();
58			if (trimmed.length >= 2 && trimmed.startsWith('"') && trimmed.endsWith('"')) {
59				return trimmed.slice(1, -1).trim();
60			}
61			return trimmed;
62		};
63	
64		for (const line of lines) {
65			if (!line.trim()) continue;
66	
67			const row: string[] = [];
68			let currentField = '';
69			let inQuotes = false;
70	
71			for (let i = 0; i < line.length; i++) {
72				const char = line[i];
73	
74				if (char === '"') {
75					// Handle escaped quotes
76					if (inQuotes && line[i + 1] === '"') {
77						currentField += '"';
78						i++; // Skip next quote
79					} else {
80						inQuotes = !inQuotes;
81					}
82				} else if (char === ',' && !inQuotes) {
83					row.push(stripOuterQuotes(currentField));
84					currentField = '';
85				} else {
86					currentField += char;
87				}
88			}
89	
90			// Add the last field
91			row.push(stripOuterQuotes(currentField));
92			result.push(row);
93		}
94	
95		return result;
96	}
97	
98	/**
99	 * Parse a date string to `YYYY-MM-DD`.
100	 *
101	 * Accepts `YYYY-MM-DD`, `MM/DD/YYYY`, `DD MMM YYYY` / `DD-MMM-YY`, and
102	 * `DD Month YYYY`. Returns `null` when no format matches.
103	 */
104	export function parseFlexibleDate(dateStr: string): string | null {
105		try {
106			// Remove any leading/trailing whitespace
107			dateStr = dateStr.trim();
108	
109			// Try YYYY-MM-DD format (new EQ Bank format)
110			const ymdMatch = dateStr.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
111			if (ymdMatch) {
112				const [, year, month, day] = ymdMatch;
113				return `${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}`;
114			}
115	
116			// Try MM/DD/YYYY format
117			const mdyMatch = dateStr.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
