/**
 * Low-level CSV primitives shared by the bank-transaction parsers
 * (`BaseCSVParser`) and the historical-expense importer (`expenseImportCsv`).
 *
 * These were originally protected methods on `BaseCSVParser`; they are extracted
 * here as pure functions so a second consumer can reuse the exact same
 * tokenizer / date / amount handling without subclassing a bank parser or
 * duplicating the logic. `BaseCSVParser` now delegates to them, so the 7 bank
 * parsers' test suites act as the oracle guaranteeing behaviour is unchanged.
 */

const MONTH_ABBREVIATIONS: Record<string, string> = {
	jan: '01',
	feb: '02',
	mar: '03',
	apr: '04',
	may: '05',
	jun: '06',
	jul: '07',
	aug: '08',
	sep: '09',
	oct: '10',
	nov: '11',
	dec: '12'
};

const MONTH_FULL_NAMES: Record<string, string> = {
	january: '01',
	february: '02',
	march: '03',
	april: '04',
	may: '05',
	june: '06',
	july: '07',
	august: '08',
	september: '09',
	october: '10',
	november: '11',
	december: '12'
};

/**
 * Tokenize a CSV string into rows and columns.
 *
 * Handles quoted fields containing commas, escaped `""` quotes, and strips a
 * surviving surrounding `"..."` pair left by double-encoded exports (EQ Bank
 * emits `"""-$33.00"""`). Blank lines are skipped.
 */
export function tokenizeCsv(csvContent: string): string[][] {
	const lines = csvContent.split(/\r?\n/);
	const result: string[][] = [];

	// Strip a surviving surrounding "..." pair from a finalized field.
	// EQ Bank exports double-encoded values like `"""-$33.00"""`, which the
	// standard unwrap above reduces to `"-$33.00"` (literal " still present).
	const stripOuterQuotes = (field: string): string => {
		const trimmed = field.trim();
		if (trimmed.length >= 2 && trimmed.startsWith('"') && trimmed.endsWith('"')) {
			return trimmed.slice(1, -1).trim();
		}
		return trimmed;
	};

	for (const line of lines) {
		if (!line.trim()) continue;

		const row: string[] = [];
		let currentField = '';
		let inQuotes = false;

		for (let i = 0; i < line.length; i++) {
			const char = line[i];

			if (char === '"') {
				// Handle escaped quotes
				if (inQuotes && line[i + 1] === '"') {
					currentField += '"';
					i++; // Skip next quote
				} else {
					inQuotes = !inQuotes;
				}
			} else if (char === ',' && !inQuotes) {
				row.push(stripOuterQuotes(currentField));
				currentField = '';
			} else {
				currentField += char;
			}
		}

		// Add the last field
		row.push(stripOuterQuotes(currentField));
		result.push(row);
	}

	return result;
}

/**
 * Parse a date string to `YYYY-MM-DD`.
 *
 * Accepts `YYYY-MM-DD`, `MM/DD/YYYY`, `DD MMM YYYY` / `DD-MMM-YY`, and
 * `DD Month YYYY`. Returns `null` when no format matches.
 */
export function parseFlexibleDate(dateStr: string): string | null {
	try {
		// Remove any leading/trailing whitespace
		dateStr = dateStr.trim();

		// Try YYYY-MM-DD format (new EQ Bank format)
		const ymdMatch = dateStr.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
		if (ymdMatch) {
			const [, year, month, day] = ymdMatch;
			return `${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}`;
		}

		// Try MM/DD/YYYY format
		const mdyMatch = dateStr.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
		if (mdyMatch) {
			const [, month, day, year] = mdyMatch;
			return `${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}`;
		}

		// Try DD MMM YYYY format (e.g., "31 May 2025" or "31-May-25")
		const dmmyMatch = dateStr.match(/^(\d{1,2})[\s-]([A-Za-z]{3})[.\s-]*(\d{2,4})$/);
		if (dmmyMatch) {
			const [, day, monthStr, year] = dmmyMatch;
			const month = MONTH_ABBREVIATIONS[monthStr.toLowerCase()];
			if (month) {
				const fullYear = year.length === 2 ? `20${year}` : year;
				return `${fullYear}-${month}-${day.padStart(2, '0')}`;
			}
		}

		// Try DD Mon YYYY format with full month name
		const dmonyMatch = dateStr.match(/^(\d{1,2})\s+([A-Za-z]+)\s+(\d{4})$/);
		if (dmonyMatch) {
			const [, day, monthStr, year] = dmonyMatch;
			const month = MONTH_FULL_NAMES[monthStr.toLowerCase()];
			if (month) {
				return `${year}-${month}-${day.padStart(2, '0')}`;
			}
		}

		return null;
	} catch {
		return null;
	}
}

/**
 * Parse an amount string to a number, handling currency symbols, thousands
 * separators, surrounding quotes, and `(...)` accounting negatives.
 *
 * Returns `null` when the string does not contain a parseable number. The sign
 * is preserved as written — callers apply any per-source sign convention.
 */
export function parseCsvAmount(amountStr: string): number | null {
	try {
		// Trim whitespace and any surrounding quote characters left over from
		// double-encoded CSV exports (e.g. EQ Bank emits `"""-$33.00"""` which
		// unwraps once to a value still containing literal " characters).
		amountStr = amountStr
			.trim()
			.replace(/^["']+|["']+$/g, '')
			.trim();

		// Check if amount is in parentheses (negative)
		const isNegative = amountStr.startsWith('(') && amountStr.endsWith(')');
		if (isNegative) {
			amountStr = amountStr.slice(1, -1);
		}

		// Remove currency symbols, commas, whitespace, and any embedded quotes
		amountStr = amountStr.replace(/[$,\s"']/g, '');

		// Parse the number
		const amount = parseFloat(amountStr);
		if (isNaN(amount)) return null;

		return isNegative ? -Math.abs(amount) : amount;
	} catch {
		return null;
	}
}

/** Remove a leading UTF-8 BOM (Byte Order Mark) if present. */
export function removeBom(content: string): string {
	if (content.charCodeAt(0) === 0xfeff) {
		return content.slice(1);
	}
	return content;
}

