/**
 * Pure import plan for the historical-expense CSV import.
 *
 * Given the parsed file rows, the receipts already in the family's records for
 * the same date range, and the family's existing category names, works out:
 * - which rows to actually insert (count-based dedup, so re-importing the same
 *   file is a no-op),
 * - how many rows were skipped as duplicates,
 * - which category names the import will have to create (so the UI can warn that
 *   they'll land in Uncategorized until filed in the hierarchy editor).
 *
 * Mirrors `transactionDedup.computeImportPlan` — the dedup is the same
 * count-based algorithm, extended with the category name in the match key
 * because a historical expense's identity includes its category. Design:
 * docs/plans/2026-07-09-spending-report-design.md
 */

import type { ParsedExpenseImportRow } from './expenseImportCsv';

/**
 * Minimal shape of an existing receipt needed for dedup: only the fields that
 * form the match key. `categoryName` is the name of the receipt's assigned
 * category (or `null` for Uncategorized), joined in by the caller.
 */
export interface ExistingReceiptForDedup {
	transaction_date: string | null;
	merchant_name: string | null;
	total_amount: number | null;
	categoryName: string | null;
}

export interface ExpenseImportPlan {
	toInsert: ParsedExpenseImportRow[];
	duplicatesSkipped: number;
	/** Distinct category names (original casing) referenced by `toInsert` that
	 * don't yet exist in the family — these will be created on import. */
	newCategoryNames: string[];
}

/** Case-insensitive category token for the match key (categories are unique per
 * family case-insensitively); `null` → a distinct "uncategorized" token. */
const categoryToken = (name: string | null): string =>
	name === null ? '�uncategorized' : name.trim().toLowerCase();

const keyOf = (r: {
	transaction_date: string | null;
	merchant_name: string | null;
	total_amount: number | null;
	categoryName: string | null;
}): string =>
	`${r.transaction_date ?? ''}|${(r.merchant_name ?? '').trim()}|${r.total_amount ?? ''}|${categoryToken(r.categoryName)}`;

export function computeExpenseImportPlan(
	fileRows: ParsedExpenseImportRow[],
	existingReceipts: ExistingReceiptForDedup[],
	existingCategoryNames: string[]
): ExpenseImportPlan {
	const dbCounts = new Map<string, number>();
	for (const r of existingReceipts) {
		const k = keyOf(r);
		dbCounts.set(k, (dbCounts.get(k) ?? 0) + 1);
	}

	const fileGroups = new Map<string, ParsedExpenseImportRow[]>();
	for (const r of fileRows) {
		const k = keyOf(r);
		const group = fileGroups.get(k) ?? [];
		group.push(r);
		fileGroups.set(k, group);
	}

	const toInsert: ParsedExpenseImportRow[] = [];
	let duplicatesSkipped = 0;
	for (const [key, group] of fileGroups) {
		const dbCount = dbCounts.get(key) ?? 0;
		const insertCount = Math.max(0, group.length - dbCount);
		toInsert.push(...group.slice(0, insertCount));
		duplicatesSkipped += group.length - insertCount;
	}

	// New categories: only those referenced by rows we'll actually insert, and
	// only names the family doesn't already have (case-insensitive). Preserve
	// the file's original casing and de-dup by lowercased name.
	const existing = new Set(existingCategoryNames.map((n) => n.trim().toLowerCase()));
	const newCategoryNames: string[] = [];
	const seen = new Set<string>();
	for (const r of toInsert) {
		if (r.categoryName === null) continue;
		const lower = r.categoryName.trim().toLowerCase();
		if (existing.has(lower) || seen.has(lower)) continue;
		seen.add(lower);
		newCategoryNames.push(r.categoryName.trim());
	}

	return { toInsert, duplicatesSkipped, newCategoryNames };
}

/** One row for the `expense_categories` join table linking a receipt to a category. */
export interface ExpenseCategoryLink {
	receipt_id: string;
	category_id: string;
	categorization_source: 'manual';
}

/**
 * Pair each newly-inserted receipt with its category id.
 *
 * `insertedReceiptIds[i]` is the id of the receipt created from `rows[i]` (the
 * caller inserts in order and reads ids back in order). Rows with a `null`
 * category, or whose category name has no id in the map, contribute no link and
 * are left Uncategorized. Historical imports are always `'manual'`.
 */
export function buildExpenseCategoryLinks(
	insertedReceiptIds: string[],
	rows: ParsedExpenseImportRow[],
	categoryIdByName: Map<string, string>
): ExpenseCategoryLink[] {
	const links: ExpenseCategoryLink[] = [];
	const n = Math.min(insertedReceiptIds.length, rows.length);
	for (let i = 0; i < n; i++) {
		const name = rows[i].categoryName;
		if (name === null) continue;
		const categoryId = categoryIdByName.get(name.trim().toLowerCase());
		if (!categoryId) continue;
		links.push({
			receipt_id: insertedReceiptIds[i],
			category_id: categoryId,
			categorization_source: 'manual'
		});
	}
	return links;
}

