1	/**
2	 * ExpenseImportService
3	 *
4	 * Imports historical Expenses from a CSV/XLS/XLSX file. Because Expenses are
5	 * computed (receipts + expense_categories + categories), each file row becomes:
6	 *   - a `receipts` row (imageless: `receipt_image_path` NULL, `suspicious_date`
7	 *     false — these are intentional old entries), created the same way as a
8	 *     manual receipt, and
9	 *   - an `expense_categories` link to a category resolved (or created) by name.
10	 *
11	 * This service is the imperative shell around three pure functions
12	 * (`parseExpenseImportCsv`, `computeExpenseImportPlan`, `buildExpenseCategoryLinks`)
13	 * — it reads the file, talks to Supabase, and lets the pure core do the logic.
14	 * A two-step flow (`buildPreview` → `commit`) lets the page show a confirmation
15	 * before writing. Design: docs/plans/2026-07-09-spending-report-design.md
16	 */
17	
18	import type { SupabaseClient } from '@supabase/supabase-js';
19	import { convertExcelToCSV, isExcelFile } from './ExcelToCSVConverter';
20	import { CategoryService } from './CategoryService';
21	import { parseExpenseImportCsv, type ParsedExpenseImportRow } from '$lib/utils/expenseImportCsv';
22	import {
23		computeExpenseImportPlan,
24		buildExpenseCategoryLinks,
25		type ExistingReceiptForDedup
26	} from '$lib/utils/expenseImportPlan';
27	
28	/** Everything the confirmation UI needs, plus the exact rows to commit. */
29	export interface ExpenseImportPreview {
30		/** Per-row parse problems (bad date/amount/merchant); those rows are dropped. */
31		parseErrors: string[];
32		/** How many rows parsed cleanly (before dedup). */
33		totalParsed: number;
34		/** Rows that will actually be created (duplicates already removed). */
35		toInsert: ParsedExpenseImportRow[];
36		/** Count of rows skipped because an identical expense already exists. */
37		duplicatesSkipped: number;
38		/** Category names that don't exist yet and will be created (Uncategorized). */
39		newCategoryNames: string[];
40	}
41	
42	export interface ExpenseImportResult {
43		imported: number;
44		categoriesCreated: number;
45	}
46	
47	/** Chunk size for batch inserts, to keep request payloads bounded. */
48	const INSERT_CHUNK = 500;
49	
50	interface ReceiptDedupEmbed {
51		transaction_date: string | null;
52		merchant_name: string | null;
53		total_amount: number | null;
54		expense_categories: { categories: { name: string | null } | null } | null;
55	}
56	
57	export class ExpenseImportService {
58		private supabase: SupabaseClient;
59		private categoryService: CategoryService;
60	
61		constructor(supabase: SupabaseClient) {
62			this.supabase = supabase;
63			this.categoryService = new CategoryService(supabase);
64		}
65	
66		/** Read a CSV/XLS/XLSX File into CSV text (Excel is converted first). */
67		async readCsvText(file: File): Promise<string> {
68			return new Promise((resolve, reject) => {
69				const reader = new FileReader();
70				reader.onload = (e) => {
71					try {
72						if (isExcelFile(file)) {
73							resolve(convertExcelToCSV(e.target?.result as ArrayBuffer));
74						} else {
75							resolve((e.target?.result as string) ?? '');
76						}
77					} catch (err) {
78						reject(err instanceof Error ? err : new Error('Failed to read file'));
79					}
80				};
81				reader.onerror = () => reject(new Error('Failed to read file'));
82				if (isExcelFile(file)) {
83					reader.readAsArrayBuffer(file);
84				} else {
85					reader.readAsText(file);
86				}
87			});
88		}
89	
90		/**
91		 * Parse the file and compute what an import would do, without writing
92		 * anything. Loads the family's categories and the receipts already recorded
93		 * in the file's date range so dedup and the new-category warning are accurate.
