/**
 * ExpenseImportService
 *
 * Imports historical Expenses from a CSV/XLS/XLSX file. Because Expenses are
 * computed (receipts + expense_categories + categories), each file row becomes:
 *   - a `receipts` row (imageless: `receipt_image_path` NULL, `suspicious_date`
 *     false — these are intentional old entries), created the same way as a
 *     manual receipt, and
 *   - an `expense_categories` link to a category resolved (or created) by name.
 *
 * This service is the imperative shell around three pure functions
 * (`parseExpenseImportCsv`, `computeExpenseImportPlan`, `buildExpenseCategoryLinks`)
 * — it reads the file, talks to Supabase, and lets the pure core do the logic.
 * A two-step flow (`buildPreview` → `commit`) lets the page show a confirmation
 * before writing. Design: docs/plans/2026-07-09-spending-report-design.md
 */

import type { SupabaseClient } from '@supabase/supabase-js';
import { convertExcelToCSV, isExcelFile } from './ExcelToCSVConverter';
import { CategoryService } from './CategoryService';
import { parseExpenseImportCsv, type ParsedExpenseImportRow } from '$lib/utils/expenseImportCsv';
import {
	computeExpenseImportPlan,
	buildExpenseCategoryLinks,
	type ExistingReceiptForDedup
} from '$lib/utils/expenseImportPlan';

/** Everything the confirmation UI needs, plus the exact rows to commit. */
export interface ExpenseImportPreview {
	/** Per-row parse problems (bad date/amount/merchant); those rows are dropped. */
	parseErrors: string[];
	/** How many rows parsed cleanly (before dedup). */
	totalParsed: number;
	/** Rows that will actually be created (duplicates already removed). */
	toInsert: ParsedExpenseImportRow[];
	/** Count of rows skipped because an identical expense already exists. */
	duplicatesSkipped: number;
	/** Category names that don't exist yet and will be created (Uncategorized). */
	newCategoryNames: string[];
}

export interface ExpenseImportResult {
	imported: number;
	categoriesCreated: number;
}

/** Chunk size for batch inserts, to keep request payloads bounded. */
const INSERT_CHUNK = 500;

interface ReceiptDedupEmbed {
	transaction_date: string | null;
	merchant_name: string | null;
	total_amount: number | null;
	expense_categories: { categories: { name: string | null } | null } | null;
}

export class ExpenseImportService {
	private supabase: SupabaseClient;
	private categoryService: CategoryService;

	constructor(supabase: SupabaseClient) {
		this.supabase = supabase;
		this.categoryService = new CategoryService(supabase);
	}

	/** Read a CSV/XLS/XLSX File into CSV text (Excel is converted first). */
	async readCsvText(file: File): Promise<string> {
		return new Promise((resolve, reject) => {
			const reader = new FileReader();
			reader.onload = (e) => {
				try {
					if (isExcelFile(file)) {
						resolve(convertExcelToCSV(e.target?.result as ArrayBuffer));
					} else {
						resolve((e.target?.result as string) ?? '');
					}
				} catch (err) {
					reject(err instanceof Error ? err : new Error('Failed to read file'));
				}
			};
			reader.onerror = () => reject(new Error('Failed to read file'));
			if (isExcelFile(file)) {
				reader.readAsArrayBuffer(file);
			} else {
				reader.readAsText(file);
			}
		});
	}

	/**
	 * Parse the file and compute what an import would do, without writing
	 * anything. Loads the family's categories and the receipts already recorded
	 * in the file's date range so dedup and the new-category warning are accurate.
	 */
	async buildPreview(familyId: string, file: File): Promise<ExpenseImportPreview> {
		const text = await this.readCsvText(file);
		return this.previewFromText(familyId, text);
	}

	/** The DB + pure-logic half of {@link buildPreview}, split out so it can be
	 * exercised without a browser `FileReader`. */
	async previewFromText(familyId: string, text: string): Promise<ExpenseImportPreview> {
		const { rows, errors } = parseExpenseImportCsv(text);

		const categories = await this.categoryService.getFamilyCategories(familyId);
		const existing = rows.length > 0 ? await this.loadExistingReceipts(rows) : [];
		const plan = computeExpenseImportPlan(
			rows,
			existing,
			categories.map((c) => c.name)
		);

		return {
			parseErrors: errors,
			totalParsed: rows.length,
			toInsert: plan.toInsert,
			duplicatesSkipped: plan.duplicatesSkipped,
			newCategoryNames: plan.newCategoryNames
		};
	}

	/**
	 * Create the receipts and their category links for the previewed rows.
	 * Resolves (creating as needed) every category, inserts the receipts in order,
	 * then links each receipt to its category. Returns counts for the summary.
	 */
	async commit(familyId: string, toInsert: ParsedExpenseImportRow[]): Promise<ExpenseImportResult> {
		if (toInsert.length === 0) {
			return { imported: 0, categoriesCreated: 0 };
		}

		const { map, created } = await this.resolveCategoryIds(familyId, toInsert);
		const insertedIds = await this.insertReceipts(toInsert);
		const links = buildExpenseCategoryLinks(insertedIds, toInsert, map);
		await this.insertExpenseCategories(links);

		return { imported: insertedIds.length, categoriesCreated: created };
	}

	/** Load existing receipts in the file's date range, flattened for dedup. */
	private async loadExistingReceipts(
		rows: ParsedExpenseImportRow[]
	): Promise<ExistingReceiptForDedup[]> {
		const dates = rows.map((r) => r.transaction_date).sort();
		const minDate = dates[0];
		const maxDate = dates[dates.length - 1];

		const { data, error } = await this.supabase
			.from('receipts')
			.select(
				`transaction_date, merchant_name, total_amount, expense_categories ( categories ( name ) )`
			)
			.gte('transaction_date', minDate)
			.lte('transaction_date', maxDate);

		if (error) throw new Error(error.message);

		const receipts = (data ?? []) as unknown as ReceiptDedupEmbed[];
		return receipts.map((r) => ({
			transaction_date: r.transaction_date,
			merchant_name: r.merchant_name,
			total_amount: r.total_amount,
			categoryName: r.expense_categories?.categories?.name ?? null
		}));
	}

	/**
	 * Build a lowercased-name → id map for every category the rows reference,
	 * creating the ones that don't exist yet. Returns the map and how many were
	 * created.
	 */
	private async resolveCategoryIds(
		familyId: string,
		toInsert: ParsedExpenseImportRow[]
	): Promise<{ map: Map<string, string>; created: number }> {
		const categories = await this.categoryService.getFamilyCategories(familyId);
		const map = new Map<string, string>(categories.map((c) => [c.name.trim().toLowerCase(), c.id]));

		const needed = new Map<string, string>(); // lowercased -> original casing
		for (const r of toInsert) {
			if (r.categoryName === null) continue;
			const lower = r.categoryName.trim().toLowerCase();
			if (!map.has(lower)) needed.set(lower, r.categoryName.trim());
		}

		let created = 0;
		for (const [lower, name] of needed) {
			try {
				const category = await this.categoryService.createCategory(familyId, name);
				map.set(lower, category.id);
				created++;
			} catch (e) {
				// A concurrent create (or a name that already existed under different
				// casing) is fine — re-fetch and resolve the id instead of failing.
				const fresh = await this.categoryService.getFamilyCategories(familyId);
				const found = fresh.find((c) => c.name.trim().toLowerCase() === lower);
				if (!found) throw e;
				map.set(lower, found.id);
			}
		}

		return { map, created };
	}

	/** Insert receipts in order, chunked, returning their new ids in row order. */
	private async insertReceipts(toInsert: ParsedExpenseImportRow[]): Promise<string[]> {
		const ids: string[] = [];
		for (let i = 0; i < toInsert.length; i += INSERT_CHUNK) {
			const chunk = toInsert.slice(i, i + INSERT_CHUNK).map((r) => ({
				merchant_name: r.merchant_name,
				total_amount: r.total_amount,
				transaction_date: r.transaction_date,
				// Intentional historical entries — never flag as suspicious.
				suspicious_date: false
			}));

			const { data, error } = await this.supabase.from('receipts').insert(chunk).select('id');
			if (error) throw new Error(error.message);

			for (const row of (data ?? []) as { id: string }[]) {
				ids.push(row.id);
			}
		}
		return ids;
	}

	/** Batch-insert the receipt → category links (chunked). */
	private async insertExpenseCategories(
		links: { receipt_id: string; category_id: string; categorization_source: 'manual' }[]
	): Promise<void> {
		for (let i = 0; i < links.length; i += INSERT_CHUNK) {
			const chunk = links.slice(i, i + INSERT_CHUNK);
			const { error } = await this.supabase
				.from('expense_categories')
				.upsert(chunk, { onConflict: 'receipt_id' });
			if (error) throw new Error(error.message);
		}
	}
}

