	const positiveAmount = Math.abs(amount);

	// #{#exp2b} Criterion 3: Round to 2 decimal places
	// #{#exp2b} Criterion 8: Use period as decimal separator
	return positiveAmount.toFixed(2);
}

/**
 * Escape CSV field (handle commas, quotes, newlines)
 * #{#exp2a} Criterion 7, 8
 *
 * @param field - Field value to escape
 * @returns Escaped field value
 */
private escapeCSVField(field: string): string {
	// #{#exp2a} Criterion 7: Quote fields containing commas
	// #{#exp2a} Criterion 8: Escape quotes with double-quotes
	if (field.includes(',') || field.includes('"') || field.includes('\n')) {
		// Escape quotes by doubling them
		const escaped = field.replace(/"/g, '""');
		return `"${escaped}"`;
	}
	return field;
}

