describe('calculateSubtotal', () => {
	it('should calculate the sum of amounts for a list of expenses', () => {
		// Criterion 3 / Test 6
		const expenses: Expense[] = [
			makeExpense({ total_amount: 125.99 }),
			makeExpense({ total_amount: 45.5 }),
			makeExpense({ total_amount: 312.0 })
		];

		expect(service.calculateSubtotal(expenses)).toBeCloseTo(483.49, 2);
	});

	it('should return 0 for an empty list', () => {
		// Test 1
		expect(service.calculateSubtotal([])).toBe(0);
	});

	it('should use absolute values (negative amounts treated as positive)', () => {
		// Criterion 2
		const expenses: Expense[] = [
			makeExpense({ total_amount: -25.5 }),
			makeExpense({ total_amount: 100 })
		];

		expect(service.calculateSubtotal(expenses)).toBeCloseTo(125.5, 2);
	});
});
